    if(late&&link&&!blocked&&link.channel==='whatsapp'&&window.SmylInbox&&window.SmylInbox.collect)menu.push('<button type="button" data-remind="'+id+'">'+(ago!==null&&ago<7?'Enviar otro recordatorio':'Enviar recordatorio')+'</button>');
