    host.querySelectorAll('[data-bs]').forEach(function(b){b.onclick=function(){var k=b.dataset.bs.split(':'),st=steps.find(function(x){return x.id===k[0];});if(!st)return;(k[1]!=null?st.extra[Number(k[1])]:st).run();};});
