  function renderOnlineCheck(form){var host=form.querySelector('[data-payment-check]'),sel=onlineSelection(form),issues=[];if(!form.elements.patient.value)issues.push('Selecciona al paciente.');else if(!sel.ids.length)issues.push('Marca los cargos que quieres cobrar con el enlace.');else if(sel.total<10)issues.push('El monto mínimo para cobrar en línea es $10.');form.elements.amount.value=sel.total?sel.total.toFixed(2):'';host.dataset.ready=String(!issues.length);host.innerHTML='<div class="finance-payment-ready"><span>'+(issues.length?'Revisa antes de generar':'Listo para generar el enlace')+'</span><strong>'+money(sel.total)+' · Enlace de pago</strong><i>'+(issues.length?'!':'✓')+'</i></div><div class="finance-payment-totals"><div><span>Cargos</span><strong>'+sel.ids.length+'</strong></div><div><span>A cobrar</span><strong>'+money(sel.total)+'</strong></div></div>'+(issues.length?'<ul>'+issues.map(function(i){return '<li>'+esc(i)+'</li>';}).join('')+'</ul>':'<p>No se registra ningún pago todavía: se registra solo cuando el paciente pague.</p>');var submit=form.querySelector('[data-payment-submit]');if(submit)submit.disabled=!!issues.length;}
